#include <stdio.h>

double apply_discount(double price, int is_member) {
    double discount = 0.0;
    if (is_member) {
        discount = 0.2;
    }
    return price * (1 - discount);
}

int main(void) {
    printf("%.2f\n", apply_discount(100, 0));
    return 0;
}
